em}.state-text{margin:4px 0 8px;font-size:14px;color:var(--foreground)}.state small{display:block;line-height:1.5}footer{padding-top:24px;border-top:1px solid var(--border);font-size:12px;color:var(--text-muted);line-height:1.7}@media(max-width:650px){.two{grid-template-columns:1fr}.states{grid-template-columns:1fr}.swatches{grid-template-columns:repeat(2,1fr)}.intro{gap:16px}.intro>img{width:80px;height:80px}h1{font-size:2.4rem}header>a:last-child{font-size:11px}nav{gap:16px}.system{padding-left:20px;padding-right:20px}section{padding:28px 0}}
.receipt-sample{max-width:800px;margin-top:20px}.receipt-sample h3{margin:0 0 8px;font:500 18px/1.3 var(--font-body)}.receipt-sample p{margin:0 0 12px;font-size:14px;line-height:1.6;color:var(--text-secondary)}
